<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']=='POST' && isset($_POST['plan_name'])){ $n=mysqli_real_escape_string($conn,$_POST['plan_name']);$d=(int)$_POST['duration'];$p=(float)$_POST['price'];$desc=mysqli_real_escape_string($conn,$_POST['description']); mysqli_query($conn,"INSERT INTO subscription_plans(plan_name,duration_months,price,description) VALUES('$n',$d,$p,'$desc')"); }
$plans=mysqli_query($conn,"SELECT * FROM subscription_plans");$pays=mysqli_query($conn,"SELECT p.*,u.full_name,sp.plan_name FROM payments p JOIN members m ON p.member_id=m.id JOIN users u ON m.user_id=u.id JOIN subscription_plans sp ON p.plan_id=sp.id ORDER BY p.id DESC"); ?>
<!DOCTYPE html><html><head><title>Plans</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Plans & Payments</h1><div class="grid" style="padding:0"><form class="form" method="post"><h2>Add Subscription Plan</h2><label>Plan</label><input name="plan_name" required><label>Duration Months</label><input name="duration" type="number" required><label>Price</label><input name="price" type="number" step=".01" required><label>Description</label><textarea name="description"></textarea><button>Save Plan</button></form><div class="card"><h2>Available Plans</h2><?php while($r=mysqli_fetch_assoc($plans)):?><p><b><?=e($r['plan_name'])?></b> - ₱<?=number_format($r['price'],2)?> / <?=$r['duration_months']?> month(s)</p><?php endwhile;?></div></div><h2>Payment Records</h2><table class="table"><tr><th>Invoice</th><th>Member</th><th>Plan</th><th>Amount</th><th>Date</th><th>Due</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($pays)):?><tr><td><?=e($r['invoice_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['plan_name'])?></td><td>₱<?=number_format($r['amount'],2)?></td><td><?=$r['payment_date']?></td><td><?=$r['due_date']?></td><td><span class="badge"><?=$r['status']?></span></td></tr><?php endwhile;?></table></main></div></body></html>
